Hypothesis HLaligned : hl_aligned_alloc L = 0x8269c.
Hypothesis HLscr : hl_scr_aligned L = 4096.
Hypothesis H1046 : forall G LB M, art_alloc_rep FSG rn G LB M -> cellA M 0x104f8 1 4.
